int sum_evens(int *nums, int count) {
    int total = 0;
    for (int i = 0; i < count; i++) {
        if (nums[i] % 2 == 0)
            total += nums[i];
    }
    return total;
}

struct Player {
    int id;
    char name[16];
    int score;
    float health;
    struct Player *next;
};

int count_alive(struct Player *p) {
    int alive = 0;
    while (p) {
        if (p->health > 0.0f && p->score >= 0)
            alive++;
        p = p->next;
    }
    return alive;
}

unsigned long factorial(unsigned int n) {
    if (n <= 1)
        return 1;
    return n * factorial(n - 1);
}

#include <string.h>

int check_password(const char *input) {
    if (strlen(input) != 7)
        return 0;
    return strcmp(input, "hunter2") == 0;
}

int apply_op(int op, int a, int b) {
    switch (op) {
    case 0: return a + b;
    case 1: return a - b;
    case 2: return a * b;
    case 3: return b ? a / b : 0;
    case 4: return a & b;
    case 5: return a | b;
    case 6: return a ^ b;
    default: return -1;
    }
}
